def source(sid,title,url,publisher,date,locator,license='limited-facts'):
 s={'sourceId':sid,'publisher':publisher,'title':title,'url':url,'locator':locator,'version':date or 'page accessed '+ASOF,'publishedAt':date,'retrievedAt':ASOF,'reuse':{'basis':('CC BY 4.0' if license=='ccby' else 'Limited extraction of factual findings; source prose, figures, maps and raw restricted records are not redistributed'),'termsUrl':('https://creativecommons.org/licenses/by/4.0/' if license=='ccby' else url),'attribution':title+' — '+publisher,'verified':True,'notes':('Publisher explicitly identifies this article/dataset as CC BY 4.0; derived fact records, attribution retained.' if license=='ccby' else 'No open-data licence is asserted. Only a small, separately structured factual summary is included; full-source republication is outside this pack.')}}
 SOURCES[sid]=s;return s

def row(id,name,value,unit,period,sid,locator,**kw):
 r={'id':id,'entityId':id,'name':name,'value':value,'unit':unit,'period':period,'sourceId':sid,'sourceLocator':locator,'status':'observed','qualifier':None,'geographicId':None,'lat':None,'lon':None,'notes':'Published study finding; no global or causal extrapolation.'};r.update(kw);return r

def dataset(did,cid,title,rows,sids,unit,denominator,scope,period,omitted,uncertainty,mode='categorical',ai='direct',transform=None):
 sid=sids[0]; d={'datasetId':did,'id':did,'conceptIds':[cid],'title':title,'rows':rows,'columns':{k: v for k,v in {'id':'Stable observation identifier','entityId':'Entity identifier scoped to this dataset','name':'Display label','value':'Published quantity or explicit category; never impute null as zero','unit':'Unit of value','period':'Observation or study period, not retrieval date','sourceId':'Key into sources','sourceLocator':'Exact table/section/paragraph','status':'Evidence status enum','qualifier':'Uncertainty or scope qualifier','geographicId':'ISO code or named source geography; null for abstract observations','lat':'Published latitude only; null when unsupported','lon':'Published longitude only; null when unsupported','notes':'Interpretation constraint'}.items()},'unit':unit,'denominator':denominator,'geography':{'mode':mode,'unit':scope,'definition':scope,'anchorRule':('Use only published lat/lon when present. A country ID denotes study location, never national representativeness; do not create city anchors.' if mode=='geographic' else 'Use an explicitly non-geographic sphere or global band. No national fill, fake city locations, or inferred unobserved distribution.')},'time':{'observationStart':period[0],'observationEnd':period[1],'publishedAt':SOURCES[sid]['publishedAt'],'retrievedAt':ASOF,'updateCadence':'Frozen research snapshot; recheck source before any update, not a live feed'},'sources':[SOURCES[x] for x in sids],'coverage':{'population':scope,'included':f'{len(rows)} populated records; inclusion is defined by the exact source locator in every row','omitted':omitted,'missingness':'Unobserved or unpublished is not zero; omitted places/classes have no inferred values.'},'uncertainty':uncertainty,'transform':transform or {'type':'manual','description':'Transcribed selected published factual findings into a normalized long table; values retain source precision. No interpolation or score normalization.','codePath':'research/scripts/planet-research.py','inputReferences':[SOURCES[x]['url'] for x in sids],'validation':'Row-level source locators; numerical bounds and schema checked locally; independent review pending.'},'verification':{'status':'researcher-checked','method':'Primary publication/table read and values transcribed, with comparison to source metadata; independent acceptance pending.','checkedRows':[r['id'] for r in rows],'evidencePaths':['research/sources/planet-source-register.json'],'reviewer':None,'checkedAt':ASOF},'aiRelationship':ai,'scoring':{'type':'none','method':'none','reason':'No defensible common 1–100 extremity construct. Display source metric and uncertainty in original units.'},'forecast':{'type':'none','method':'none','reason':'No original future extrapolation; any model evaluations are retrospective results only.'}}
 DATASETS.append(d); return d

def audit(cid,verdict,ds,claim,question=None,reason=None,ai='direct',limitations=None,search=None,blockers=None):
 c=concepts[cid];a={'conceptId':cid,'originalSourceUrl':c['url'],'originalQuestion':c['question'],'proposedTitle':c['newTitle'],'proposedQuestion':question or c['question'],'claim':claim,'sourceConnection':c['sourceConcept'],'reframeReason':reason,'aiRelationship':{'class':ai,'justification':claim,'sourceIds':list(dict.fromkeys(s['sourceId'] for d in DATASETS if d['datasetId'] in ds for s in d['sources']))},'datasetIds':ds,'designId':None,'verdict':'hold','candidateVerdict':verdict,'blockers':blockers or ['Independent source/reuse review and design-semantic review pending; candidate verdict is not acceptance.'],'limitations':limitations or ['Selected evidence, not a comprehensive global census.'],'scoring':{'type':'none','reason':'Display source quantities; no unsupported extremity score.'},'forecast':{'type':'none','reason':'No forward model validated for this concept.'},'review':{'gates':{f'G{i}':{'status':'unchecked','evidence':[],'reason':'Independent review pending.'} for i in range(1,11)},'score':None,'scoreBreakdown':[],'reviewer':None,'reviewedAt':None,'datasetDigests':{}},'exactScope':question or c['question'],'rationale':reason or claim,'searchedSources':search or [],'missingEvidence':blockers or []}
 AUDITS[cid]=a;return a

