source('planet-wine','Wine Quality dataset, UCI Machine Learning Repository','https://archive.ics.uci.edu/dataset/186/wine+quality','Cortez, Cerdeira, Almeida, Matos and Reis / UCI','2009-10-07','winequality-red.csv and winequality-white.csv; quality column; repository licence','ccby')
