(ROOT/'sources/planet-wine-records.json').write_text(json.dumps(raw,separators=(',',':'))+'\n')
(ROOT/'sources/planet-wine-download.json').write_text(json.dumps({'url':u,'retrievedAt':ASOF,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'files':z.namelist(),'rowCount':len(raw)},indent=2)+'\n')
